"use client";
import { useEffect, useRef, useState } from "react";
import { GlassButton } from "./glass-button.jsx";
import "./glass-surface.css";
import "./glass-card.css";
import "./glass-ai.css";

// Sound comes from glass-sound.jsx when it is loaded and switched on
const gsnd = (n, o) => { const g = typeof window !== "undefined" && window.glassSound; return g ? g.play(n, o) : false; };

const I = ({ d, w = 2 }) => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={w} strokeLinecap="round" strokeLinejoin="round"><path d={d} /></svg>
);
const CHEVRON = "M6 9l6 6 6-6";
const TICK = "M6 12.5l4 4 8-9";

/**
 * GlassChatMessage
 * role      "assistant" | "user"
 * name      optional label above an assistant message
 * avatar    element shown beside an assistant message
 * actions   elements under the message (copy, retry)
 * children  the message. Put thinking steps, tool calls and sources in here too.
 */
export function GlassChatMessage({ role = "assistant", name, avatar, actions, effect = "flat", children }) {
  return (
    <div className="gcm" data-role={role}>
      {role === "assistant" && <span className="gcm-avatar" aria-hidden="true">{avatar}</span>}
      <div className="gcm-main">
        {name && <span className="gcm-name">{name}</span>}
        {role === "user" ? <div className="gcm-bubble gf" data-effect={effect}>{children}</div> : <div className="gcm-text">{children}</div>}
        {actions && <div className="gcm-actions">{actions}</div>}
      </div>
    </div>
  );
}

/**
 * GlassPromptInput: the box people type into.
 * value, onChange(text), onSend(text)
 * busy, onStop    while the assistant is working, the send button becomes Stop
 * suggestions     short prompts shown above the box; pressing one fills it
 * tools           elements at the bottom left (attach, model picker)
 * Enter sends, Shift+Enter adds a line.
 */
export function GlassPromptInput({ value = "", onChange, onSend, busy = false, onStop, suggestions = [], tools, placeholder = "Ask anything", hint, effect = "flat" }) {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${el.scrollHeight}px`;
  }, [value]);
  const send = () => {
    const text = value.trim();
    if (text && !busy && onSend) { gsnd("send"); onSend(text); }
  };
  return (
    <div className="gpi">
      {suggestions.length > 0 && (
        <div className="gpi-chips">
          {suggestions.map((s) => (
            <GlassButton key={s} variant="secondary" size="sm" effect={effect} onClick={() => { onChange && onChange(s); ref.current && ref.current.focus(); }}>{s}</GlassButton>
          ))}
        </div>
      )}
      <div className="gf gpi-box" data-effect={effect} data-multiline="">
        <textarea
          ref={ref}
          className="gf-input"
          rows={1}
          aria-label={placeholder}
          placeholder={placeholder}
          value={value}
          onChange={(e) => onChange && onChange(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
              e.preventDefault();
              send();
            }
          }}
        />
        <div className="gpi-bar">
          <div className="gpi-tools">{tools}{hint && <span className="gpi-hint">{hint}</span>}</div>
          {busy ? (
            <GlassButton iconOnly size="sm" effect={effect} aria-label="Stop" onClick={onStop}><I d="M8 8h8v8H8z" w={2.4} /></GlassButton>
          ) : (
            <GlassButton iconOnly size="sm" effect={effect} aria-label="Send" disabled={!value.trim()} onClick={send}><I d="M12 19V5M6 11l6-6 6 6" w={2.2} /></GlassButton>
          )}
        </div>
      </div>
    </div>
  );
}

/**
 * GlassThinkingSteps: what the assistant is doing, step by step.
 * steps  [{ id, label, detail?, status: "done" | "active" | "pending" }]
 */
export function GlassThinkingSteps({ title = "Working", steps = [], defaultOpen = true }) {
  const [open, setOpen] = useState(defaultOpen);
  const done = steps.filter((s) => s.status === "done").length;
  return (
    <div className="gts">
      <button type="button" className="gts-head" aria-expanded={open} onClick={() => setOpen(!open)}>
        {done === steps.length ? "Done" : title}
        <span className="gts-count">{done} of {steps.length} steps</span>
        <I d={CHEVRON} />
      </button>
      <div className="gts-panel" data-open={open ? "" : undefined} inert={open ? undefined : ""}>
        <ol className="gts-list">
          {steps.map((s) => (
            <li key={s.id} className="gts-step" data-status={s.status}>
              <span className="gts-mark" aria-hidden="true">{s.status === "done" && <I d={TICK} w={3.2} />}</span>
              <span className="gts-body">
                <span>{s.label}</span>
                {s.detail && <span className="gts-detail">{s.detail}</span>}
              </span>
            </li>
          ))}
        </ol>
      </div>
    </div>
  );
}

/**
 * GlassToolCall: one call the assistant made to a tool.
 * name      the tool, shown in monospace
 * summary   one line on what it did
 * status    "running" | "done" | "error"
 * children  the details (input and output), shown when opened
 */
export function GlassToolCall({ name, summary, status = "done", defaultOpen = false, children }) {
  const [open, setOpen] = useState(defaultOpen);
  const label = status === "running" ? "Running" : status === "error" ? "Failed" : "Done";
  return (
    <div className="gtc" data-status={status}>
      <button type="button" className="gtc-head" aria-expanded={open} onClick={() => setOpen(!open)}>
        <span className="gtc-icon" aria-hidden="true"><I d="M4 5h16v14H4zM8 10l3 2.5-3 2.5M13 15h3" w={1.75} /></span>
        <span className="gtc-name">{name}</span>
        <span className="gtc-summary">{summary}</span>
        <span className="gtc-status">{label}</span>
        <span className="gtc-chev" aria-hidden="true"><I d={CHEVRON} /></span>
      </button>
      {open && children && <pre className="gtc-body">{children}</pre>}
    </div>
  );
}

/**
 * GlassApproval: the assistant asks before it acts.
 * title, children (what will happen)
 * status   "pending" | "approved" | "denied"
 * onApprove, onDeny
 */
export function GlassApproval({ title, children, status = "pending", onApprove, onDeny, approveLabel = "Approve", denyLabel = "Don't allow", effect = "flat" }) {
  return (
    <div className="gc gap" data-level="2" data-effect={effect} data-active={status === "pending" ? "" : undefined} role="group" aria-label={title}>
      <p className="gap-title">{title}</p>
      {children && <p className="gap-text">{children}</p>}
      {status === "pending" ? (
        <div className="gap-row">
          <GlassButton size="sm" effect={effect} onClick={onApprove}>{approveLabel}</GlassButton>
          <GlassButton size="sm" variant="secondary" effect={effect} onClick={onDeny}>{denyLabel}</GlassButton>
        </div>
      ) : (
        <p className="gap-done" role="status">{status === "approved" ? "Approved" : "Not allowed"}</p>
      )}
    </div>
  );
}

/**
 * GlassQuestions: the assistant asks a few things before it starts.
 * questions   [{ id, prompt, options: [{ value, label, hint? }] }]
 * onComplete(answers)   answers is { [id]: value } ; skipped questions are left out
 * Number keys pick an option while focus is inside.
 */
export function GlassQuestions({ questions = [], onComplete, allowSkip = true, effect = "flat" }) {
  const [i, setI] = useState(0);
  const [answers, setAnswers] = useState({});
  const q = questions[i];
  const next = (nextAnswers) => {
    setAnswers(nextAnswers);
    if (i + 1 < questions.length) setI(i + 1);
    else {
      setI(questions.length);
      if (onComplete) onComplete(nextAnswers);
    }
  };
  if (!q) {
    return (
      <div className="gc gq" data-level="1" data-effect={effect}>
        <p className="gq-prompt" role="status">Thanks, that's everything.</p>
        <div className="gq-row"><GlassButton size="sm" variant="secondary" effect={effect} onClick={() => { setI(0); setAnswers({}); }}>Start again</GlassButton></div>
      </div>
    );
  }
  return (
    <div
      className="gc gq"
      data-level="1"
      data-effect={effect}
      onKeyDown={(e) => {
        const n = Number(e.key);
        if (n >= 1 && n <= q.options.length) next({ ...answers, [q.id]: q.options[n - 1].value });
      }}
    >
      <span className="gq-step">Question {i + 1} of {questions.length}</span>
      <p className="gq-prompt">{q.prompt}</p>
      <div className="gq-opts">
        {q.options.map((o, n) => (
          <button key={o.value} type="button" className="gf gq-opt" data-effect={effect} onClick={() => next({ ...answers, [q.id]: o.value })}>
            <span className="gq-opt-text">
              <span>{o.label}</span>
              {o.hint && <span className="gq-opt-hint">{o.hint}</span>}
            </span>
            <span className="gq-key" aria-hidden="true">{n + 1}</span>
          </button>
        ))}
      </div>
      <div className="gq-row">
        <GlassButton size="sm" variant="ghost" effect={effect} disabled={i === 0} onClick={() => setI(i - 1)}>Back</GlassButton>
        {allowSkip && <GlassButton size="sm" variant="ghost" effect={effect} onClick={() => next(answers)}>Skip</GlassButton>}
      </div>
    </div>
  );
}

/**
 * GlassSources: where an answer came from.
 * items  [{ id, title, domain?, href? }]
 */
export function GlassSources({ items = [] }) {
  return (
    <ol className="gsrc" aria-label="Sources">
      {items.map((s, n) => {
        const inner = (
          <>
            <span className="gsrc-n">{n + 1}</span>
            <span className="gsrc-title">{s.title}</span>
            {s.domain && <span className="gsrc-domain">{s.domain}</span>}
          </>
        );
        return (
          <li key={s.id}>
            {s.href ? <a className="gsrc-item" href={s.href} target="_blank" rel="noreferrer">{inner}</a> : <span className="gsrc-item">{inner}</span>}
          </li>
        );
      })}
    </ol>
  );
}

const short = (n) => (n >= 1000 ? `${(n / 1000).toFixed(n >= 10000 ? 0 : 1)}k` : String(n));

/**
 * GlassUsage: how much of a limit is used.
 * used, limit   numbers
 * label, unit   text, e.g. "Context" and "tokens"
 * Turns red above 85%.
 */
export function GlassUsage({ label = "Context", used = 0, limit = 1, unit = "tokens" }) {
  const pct = Math.max(0, Math.min(100, (used / limit) * 100));
  return (
    <div className="gus" data-high={pct > 85 ? "" : undefined}>
      <div className="gus-head">
        <span>{label}</span>
        <span>{short(used)} of {short(limit)} {unit}</span>
      </div>
      <div className="gpr-track" role="progressbar" aria-label={label} aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(pct)}>
        <div className="gpr-fill" style={{ "--gpr-value": pct }} />
      </div>
    </div>
  );
}

/* Parts for AI products: chat message, prompt input, thinking steps,
   tool call, approval, questions, sources and a usage meter. */

/* ---------- Chat message ---------- */
.gcm { display: flex; gap: 10px; min-width: 0; color: var(--glass-fg); font-size: 15px; line-height: 1.55; }
.gcm[data-role="user"] { justify-content: flex-end; }
.gcm-avatar { flex: none; width: 28px; height: 28px; margin-top: 2px; border-radius: 50%; display: grid; place-items: center; overflow: hidden; background: color-mix(in srgb, var(--glass-tint) 18%, #fff); }
.gcm-avatar img { width: 100%; height: 100%; object-fit: cover; }
.gcm-main { display: flex; flex-direction: column; gap: 8px; min-width: 0; max-width: 100%; }
.gcm[data-role="user"] .gcm-main { align-items: flex-end; max-width: 82%; }
.gcm[data-role="assistant"] .gcm-main { flex: 1; }
.gtc-head { min-width: 0; }
.gtc-name { flex: none; }
.gcm-name { font-size: 12.5px; font-weight: 600; color: rgb(var(--glass-shadow) / 0.6); }
.gcm-bubble.gf { display: block; width: auto; min-height: 0; padding: 9px 14px; border-radius: 18px; line-height: 1.45; cursor: default; }
.gcm-text { display: flex; flex-direction: column; gap: 10px; min-width: 0; }
.gcm-text p { margin: 0; }
.gcm-actions { display: flex; flex-wrap: wrap; gap: 4px; margin-left: -6px; }

/* ---------- Prompt input ---------- */
.gpi { display: flex; flex-direction: column; gap: 10px; min-width: 0; }
.gpi-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.gpi-box.gf { flex-direction: column; align-items: stretch; gap: 6px; padding: 10px 10px 8px 14px; border-radius: min(var(--glass-radius), 24px); }
.gpi-box textarea.gf-input { min-height: 24px; max-height: 168px; height: auto; padding: 4px 0; resize: none; line-height: 1.45; font-size: 15px; }
.gpi-bar { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.gpi-tools { display: flex; flex-wrap: wrap; align-items: center; gap: 4px; margin-left: -6px; min-width: 0; }
.gpi-hint { font-size: 12px; color: rgb(var(--glass-shadow) / 0.5); }

/* ---------- Thinking steps ---------- */
.gts { display: flex; flex-direction: column; min-width: 0; color: var(--glass-fg); }
.gts-head { display: inline-flex; align-items: center; gap: 8px; align-self: flex-start; padding: 4px 8px 4px 0; border: 0; background: none; font: inherit; font-size: 14px; font-weight: 500; color: inherit; cursor: pointer; }
.gts-head svg { width: 15px; height: 15px; opacity: 0.55; transition: transform 0.26s cubic-bezier(0.2, 0.8, 0.2, 1); }
.gts-head[aria-expanded="true"] svg { transform: rotate(180deg); }
.gts-count { font-weight: 400; color: rgb(var(--glass-shadow) / 0.55); }
.gts-panel { display: grid; grid-template-rows: 0fr; transition: grid-template-rows 0.28s cubic-bezier(0.2, 0.8, 0.2, 1); }
.gts-panel[data-open] { grid-template-rows: 1fr; }
.gts-list { overflow: hidden; min-height: 0; margin: 0; padding: 0; list-style: none; }
.gts-step { position: relative; display: flex; gap: 12px; padding: 6px 0 6px 2px; font-size: 14px; }
/* The rail that joins one step to the next */
.gts-step:not(:last-child)::before { content: ""; position: absolute; left: 9.5px; top: 26px; bottom: -6px; width: 1px; background: rgb(var(--glass-shadow) / 0.14); }
.gts-mark { flex: none; display: grid; place-items: center; width: 16px; height: 16px; margin-top: 3px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px rgb(var(--glass-shadow) / 0.25); color: var(--glass-on-tint); }
.gts-mark svg { width: 10px; height: 10px; }
.gts-step[data-status="done"] .gts-mark { background: var(--glass-focus, var(--glass-tint)); box-shadow: none; color: #fff; }
.gts-step[data-status="active"] .gts-mark { box-shadow: inset 0 0 0 1.5px var(--glass-focus, var(--glass-tint)); }
.gts-step[data-status="active"] .gts-mark::after { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--glass-focus, var(--glass-tint)); animation: gts-pulse 1.1s ease-in-out infinite; }
@keyframes gts-pulse { 50% { transform: scale(0.5); opacity: 0.5; } }
.gts-step[data-status="pending"] { color: rgb(var(--glass-shadow) / 0.5); }
.gts-body { display: flex; flex-direction: column; min-width: 0; }
.gts-detail { font-size: 13px; color: rgb(var(--glass-shadow) / 0.58); }

/* ---------- Tool call ---------- */
.gtc { border-radius: 14px; color: var(--glass-fg); background: rgb(var(--glass-shadow) / 0.04); box-shadow: inset 0 0 0 1px rgb(var(--glass-shadow) / 0.08); min-width: 0; }
.gtc-head { display: flex; align-items: center; gap: 10px; width: 100%; padding: 10px 12px; border: 0; border-radius: inherit; background: none; font: inherit; font-size: 14px; text-align: left; color: inherit; cursor: pointer; }
.gtc-icon { display: inline-flex; opacity: 0.6; }
.gtc-icon svg, .gtc-chev svg { width: 16px; height: 16px; }
.gtc-name { flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-family: "Geist Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace; font-size: 13px; font-weight: 500; }
.gtc-icon, .gtc-chev { flex: none; }
.gtc-summary { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: rgb(var(--glass-shadow) / 0.6); }
.gtc-status { display: inline-flex; align-items: center; gap: 6px; flex: none; font-size: 12.5px; color: rgb(var(--glass-shadow) / 0.6); }
.gtc-status::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: #17a065; }
.gtc[data-status="error"] .gtc-status::before { background: var(--glass-danger); }
.gtc[data-status="running"] .gtc-status::before { width: 10px; height: 10px; background: none; border: 1.5px solid currentColor; border-right-color: transparent; animation: gb-spin 0.7s linear infinite; }
.gtc-chev { display: inline-flex; opacity: 0.5; transition: transform 0.24s cubic-bezier(0.2, 0.8, 0.2, 1); }
.gtc-head[aria-expanded="true"] .gtc-chev { transform: rotate(180deg); }
.gtc-body { margin: 0; padding: 2px 12px 12px 38px; overflow-x: auto; font-family: "Geist Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace; font-size: 12.5px; line-height: 1.55; white-space: pre-wrap; color: rgb(var(--glass-shadow) / 0.75); }

/* ---------- Approval ---------- */
.gap { gap: 12px; }
.gap-title { margin: 0; font-size: 15px; font-weight: 600; }
.gap-text { margin: 0; font-size: 14px; color: rgb(var(--glass-shadow) / 0.7); }
.gap-row { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }
.gap-done { font-size: 14px; font-weight: 500; }

/* ---------- Questions ---------- */
.gq { gap: 14px; }
.gq-step { font-size: 12.5px; font-weight: 500; color: rgb(var(--glass-shadow) / 0.55); }
.gq-prompt { margin: 0; font-size: 17px; font-weight: 600; letter-spacing: -0.01em; line-height: 1.25; }
.gq-opts { display: flex; flex-direction: column; gap: 8px; }
.gq-opt.gf { justify-content: space-between; gap: 12px; min-height: 44px; padding-block: 8px; border-radius: min(var(--glass-radius), 16px); cursor: pointer; }
.gq-opt-text { display: flex; flex-direction: column; min-width: 0; }
.gq-opt-hint { font-size: 12.5px; color: rgb(var(--glass-shadow) / 0.58); }
.gq-key { flex: none; display: grid; place-items: center; width: 22px; height: 22px; border-radius: 7px; font-size: 12px; font-weight: 500; color: rgb(var(--glass-shadow) / 0.6); background: rgb(var(--glass-shadow) / 0.07); }
.gq-row { display: flex; justify-content: space-between; gap: 10px; }

/* ---------- Sources ---------- */
.gsrc { display: flex; flex-wrap: wrap; gap: 8px; margin: 0; padding: 0; list-style: none; }
.gsrc-item { display: inline-flex; align-items: center; gap: 8px; max-width: 100%; padding: 5px 12px 5px 5px; border-radius: 999px; font-size: 13px; text-decoration: none; color: var(--glass-fg); background: rgb(var(--glass-shadow) / 0.05); box-shadow: inset 0 0 0 1px rgb(var(--glass-shadow) / 0.07); transition: background 0.15s; }
a.gsrc-item:hover { background: rgb(var(--glass-shadow) / 0.09); }
.gsrc-n { flex: none; display: grid; place-items: center; width: 20px; height: 20px; border-radius: 50%; font-size: 11.5px; font-weight: 600; color: var(--glass-on-tint); background: var(--glass-tint); }
.gsrc-title { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 500; }
.gsrc-domain { color: rgb(var(--glass-shadow) / 0.55); white-space: nowrap; }

/* ---------- Usage ---------- */
.gus { display: flex; flex-direction: column; gap: 6px; min-width: 0; color: var(--glass-fg); }
.gus-head { display: flex; justify-content: space-between; gap: 12px; font-size: 13px; font-variant-numeric: tabular-nums; }
.gus-head span:first-child { font-weight: 500; }
.gus-head span:last-child { color: rgb(var(--glass-shadow) / 0.6); }
.gus[data-high] .gus-head span:last-child { color: var(--glass-danger); }
.gus .gpr-track { height: 8px; --gpr-track: rgb(var(--glass-shadow) / 0.12); box-shadow: inset 0 0 0 1px rgb(var(--glass-shadow) / 0.06); }
.gus .gpr-fill { --gpr-fill: var(--glass-tint); }
[data-glass-tint="frost"] .gus .gpr-fill { --gpr-fill: rgb(var(--glass-shadow) / 0.7); }
.gus .gpr-fill { min-width: 6px; }
.gus[data-high] .gpr-fill { --gpr-fill: var(--glass-danger); }

.gts-head:focus-visible, .gtc-head:focus-visible, .gsrc-item:focus-visible { outline: 2px solid var(--glass-focus, var(--glass-tint)); outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) {
  .gts-panel, .gts-head svg, .gtc-chev { transition: none; }
  .gts-step[data-status="active"] .gts-mark::after { animation: none; }
}
